// TASK-0044 — V1 Per-Brain Resume State, product acceptance in real WebView2.
// No simulated DOM, no alternate renderer, no personal data: the trees under test were
// generated by task0044-seed-proof.py and die with the proof root.
//
// The claim under test (`DEC-0042` §10): three brains, each with a DIFFERENT branch, selection,
// filter, camera and details panel, come back with exactly their own state — after switching
// between them in one session, and after a REAL close and relaunch of the process — and one
// brain's record never reaches another's, although the numeric node id of `docs` is the same
// in all three brains. Every interaction is a real mouse event dispatched through the browser's
// input pipeline (CDP `Input.dispatchMouseEvent`), never a call to the product's functions.
//
//   phase 1  (process 1)  baseline; X, Y, Z each given a different state through the real UI;
//                         X -> Y -> Z -> X -> Z -> Y, every return compared value by value;
//                         a wheel burst is measured on the wire (bounded writes).
//   phase 2  (process 2)  the last active brain (Y) comes back ALONE with its state; Z and X are
//                         visited and each is exactly what it was; Actualiser does not erase the
//                         state; the selected node of X and Y is recorded for the offline phase.
//   phase 0  (no application running) the harness deletes, on disk, X's selected file and Y's
//                         whole `docs` directory (the node that X also uses as its branch id).
//   phase 3  (process 3)  X reopens: the deleted selection falls back to a valid target, the
//                         filter stays, nothing stale; Y falls back too; Z is untouched.
//
// What is compared is LOGICAL values: the record read from the catalogue (`map_brain_resume_state`),
// the selected node id and name, the panel word, the filter sentence and total, the camera numbers.
import assert from "node:assert/strict";
import { mkdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0044-[a-f0-9]+$/.test(variant));
assert([0, 1, 2, 3].includes(phase));

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainX, brainY, brainZ, rootX, rootY, rootZ, displayNames } = seed;
const IDS = { X: brainX, Y: brainY, Z: brainZ };
const ROOTS = { X: rootX, Y: rootY, Z: rootZ };
const NAMES = { X: displayNames.x, Y: displayNames.y, Z: displayNames.z };
const proofRoot = join(".filetopo-sandbox", variant);
const RESUME_KEYS = ["detailsPanelVisible", "filter", "focusNodeId", "selectedNodeId", "view"];

const readJson = async (name) => JSON.parse(await readFile(join(proofRoot, name), "utf8"));
const writeJson = (name, value) => writeFile(join(proofRoot, name), JSON.stringify(value, null, 1));

// ---- phase 0: the application is CLOSED; the source moves on -------------------------
if (phase === 0) {
  const recorded = await readJson("phase2.json");
  const removed = [];
  const fileX = join(rootX, ...recorded.selectedPath.X.split("/"));
  await rm(fileX, { force: true });
  removed.push({ brain: "X", kind: "file" });
  // Y: the whole `docs` directory — the very numeric id that X keeps as its BRANCH.
  await rm(join(rootY, "docs"), { recursive: true, force: true });
  removed.push({ brain: "Y", kind: "directory" });
  assert(!(await exists(fileX)));
  const offline = { removed, expectedRemovedX: 1, expectedRemovedY: 13 };
  await writeJson("offline.json", offline);
  console.log(JSON.stringify({ ok: true, phase, ...offline }));
  process.exit(0);
}
async function exists(path) {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}

// ---- CDP attach --------------------------------------------------------------------
let target;
for (let n = 0; n < 150; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(100);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
// Every `map_*` IPC round trip the PRODUCT itself makes, observed on the wire (CDP Network), in
// order, with its arguments. The harness's own `invoke` calls go through Runtime.evaluate and
// are recorded apart, so they can never be mistaken for what the product did.
const wireRequests = new Map();
const wireCalls = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.method === "Network.requestWillBeSent") {
    const url = event.params.request.url;
    const m = /\/(map_[a-z_]+)(?:[?#].*)?$/.exec(url);
    if (m && /ipc/.test(url) && event.params.request.method === "POST") {
      wireRequests.set(event.params.requestId, {
        command: m[1],
        body: event.params.request.postData ?? "",
        hasPostData: event.params.request.hasPostData === true,
        at: Date.now(),
      });
    }
  } else if (event.method === "Network.loadingFinished" && wireRequests.has(event.params.requestId)) {
    const request = wireRequests.get(event.params.requestId);
    // A body the browser kept aside is fetched, so that what the product SENT can be read.
    request.bodyReady =
      request.body === "" && request.hasPostData
        ? send("Network.getRequestPostData", { requestId: event.params.requestId })
            .then((r) => {
              request.body = r.postData ?? "";
            })
            .catch(() => {})
        : Promise.resolve();
    wireCalls.push(request);
    wireRequests.delete(event.params.requestId);
  }
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ?? r.exceptionDetails.exception?.value ?? JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 120000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
async function untilTrue(description, predicate, limit = 120000, interval = 150) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await predicate()) return;
    await pause(interval);
  }
  throw new Error(`timeout: ${description}`);
}
const exposedPayloads = [];
// The harness's own reads (never a product click): `map_brain_resume_state` reads the catalogue,
// `map_open` / `map_view` / `map_node_detail` / `map_change_journal` read FileTopo's own local
// state. The one exception is `map_refresh` for Y and Z, called once each as their baseline —
// the very command Actualiser calls.
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");
await send("Network.enable", { maxTotalBufferSize: 64 * 1024 * 1024, maxResourceBufferSize: 16 * 1024 * 1024 });

// ---- real input ---------------------------------------------------------------------
const centerOf = (selector) =>
  evaluate(`(() => {
    const e = document.querySelector(${JSON.stringify(selector)});
    if (!e) return null;
    e.scrollIntoView?.({ block: 'center', inline: 'center' });
    const r = e.getBoundingClientRect();
    const x = r.x + r.width / 2;
    const y = r.y + r.height / 2;
    const top = document.elementFromPoint(x, y);
    return {
      x, y, w: r.width, h: r.height,
      // What a real mouse would hit at that point: the element itself or something inside it.
      hit: !!top && (e === top || e.contains(top) || top.contains(e)),
      topmost: top ? (top.getAttribute('data-testid') || top.tagName) : null,
    };
  })()`);
/** One real left click (move, press, release) at the middle of the element. */
async function click(selector) {
  const box = await centerOf(selector);
  assert(box && box.w > 0 && box.h > 0, `click: nothing clickable at ${selector}`);
  assert(box.hit, `click: ${selector} is covered by ${box.topmost} at (${Math.round(box.x)}, ${Math.round(box.y)})`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: box.x, y: box.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: box.x, y: box.y, button: "left", buttons: 1, clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: box.x, y: box.y, button: "left", buttons: 0, clickCount: 1 });
  await pause(200);
}
/** The first listed result that is a MATCH (the list also names the ancestors, as context). */
async function clickFirstMatch() {
  const found = await evaluate(`(() => {
    const item = [...document.querySelectorAll('[data-testid="filter-result"]')].find((b) => /Correspondance/.test(b.textContent ?? ''));
    if (!item) return false;
    item.setAttribute('data-proof-click', '1');
    return true;
  })()`);
  assert(found, "no match is listed on this page");
  await click('[data-proof-click="1"]');
  await evaluate(`document.querySelector('[data-proof-click="1"]')?.removeAttribute('data-proof-click')`);
}
async function clickButtonNamed(text) {
  const found = await evaluate(`(() => {
    const b = [...document.querySelectorAll('button')].find((e) => e.textContent.trim() === ${JSON.stringify(text)});
    if (!b) return false;
    b.setAttribute('data-proof-click', '1');
    return true;
  })()`);
  assert(found, `no button named « ${text} »`);
  await click('[data-proof-click="1"]');
  await evaluate(`document.querySelector('[data-proof-click="1"]')?.removeAttribute('data-proof-click')`);
}
/** Real wheel notches over the canvas, at a point given as a fraction of its box. */
async function wheel(fx, fy, deltaY, count, gapMs = 15) {
  const box = await centerOf('[data-testid="composed-canvas"]');
  const x = box.x - box.w / 2 + box.w * fx;
  const y = box.y - box.h / 2 + box.h * fy;
  for (let i = 0; i < count; i += 1) {
    await send("Input.dispatchMouseEvent", { type: "mouseWheel", x, y, deltaX: 0, deltaY });
    if (gapMs) await pause(gapMs);
  }
}
/** One real drag of the canvas (press, moves, release) — a pan. */
async function drag(fx, fy, dx, dy) {
  const box = await centerOf('[data-testid="composed-canvas"]');
  const x = box.x - box.w / 2 + box.w * fx;
  const y = box.y - box.h / 2 + box.h * fy;
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
  for (let step = 1; step <= 12; step += 1) {
    await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: x + (dx * step) / 12, y: y + (dy * step) / 12, buttons: 1 });
    await pause(20);
  }
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: x + dx, y: y + dy, button: "left", buttons: 0, clickCount: 1 });
  await pause(200);
}

// ---- what the real screen shows -----------------------------------------------------
const screenState = () =>
  evaluate(`(() => {
    const text = (id) => document.querySelector('[data-testid="' + id + '"]')?.textContent ?? null;
    const selected = document.querySelector('[role="treeitem"][aria-selected="true"]');
    const world = document.querySelector('[data-testid="composed-world"]')?.getAttribute('transform') ?? '';
    const m = /translate\\(\\S+ \\S+\\) scale\\(\\S+\\)/.test(world) ? /translate\\((\\S+) (\\S+)\\) scale\\((\\S+)\\)/.exec(world) : null;
    const chips = [...document.querySelectorAll('[data-testid^="composition-chip-"]')].map((e) => e.getAttribute('data-brain-id'));
    const toggle = document.querySelector('[data-testid="details-panel-toggle"]');
    const count = document.querySelector('[data-testid="filter-count"]');
    const nodes = [...document.querySelectorAll('[role="treeitem"][data-node-id]')];
    return {
      chips,
      focusedChip: document.querySelector('.composition__chip--focused [data-brain-id]')?.getAttribute('data-brain-id') ?? null,
      selectedId: selected ? Number(selected.getAttribute('data-node-id')) : null,
      selectedName: selected?.querySelector('title')?.textContent ?? null,
      panelVisible: toggle ? toggle.textContent.includes('Masquer') : null,
      filterSentence: text('filter-active'),
      filterTotal: count ? Number(count.getAttribute('data-total')) : null,
      filterPage: text('filter-page'),
      view: m ? { tx: Number(m[1]), ty: Number(m[2]), scale: Number(m[3]) } : null,
      nodeIds: nodes.map((e) => Number(e.getAttribute('data-node-id'))),
      labels: nodes.map((e) => e.getAttribute('aria-label') ?? ''),
      projection: text('projection-controls'),
    };
  })()`);
const resumeOf = async (brainId) => invoke("map_brain_resume_state", { brainId });
const closeTo = (a, b) => Math.abs(a - b) <= 1e-6 * Math.max(1, Math.abs(a), Math.abs(b));
const sameView = (a, b) => a !== null && b !== null && closeTo(a.scale, b.scale) && closeTo(a.tx, b.tx) && closeTo(a.ty, b.ty);

/** Waits until a brain's record has settled (unchanged for a while) and satisfies `predicate`. */
async function settledRecord(brainId, predicate, label, limit = 30000) {
  let last = "";
  let since = Date.now();
  const start = Date.now();
  while (Date.now() - start < limit) {
    const record = await resumeOf(brainId);
    const text = JSON.stringify(record);
    if (text !== last) {
      last = text;
      since = Date.now();
    } else if (Date.now() - since >= 900 && predicate(record)) return record;
    await pause(150);
  }
  throw new Error(`timeout: the record of ${brainId} never settled (${label}): ${last}`);
}
function assertRecordShape(record, where) {
  assert.deepEqual(Object.keys(record).sort(), RESUME_KEYS, `${where}: the record has exactly its five keys`);
  assert.deepEqual(Object.keys(record.filter).sort(), ["availability", "kinds", "state"], `${where}: the filter keys`);
  if (record.view !== null) assert.deepEqual(Object.keys(record.view).sort(), ["scale", "tx", "ty"], `${where}: the camera keys`);
  const text = JSON.stringify(record);
  assert(!/ftf1|cursor|path|name|stable|identity|racine|\\/.test(text), `${where}: nothing but ids, numbers and words: ${text}`);
}

// ---- confidentiality -----------------------------------------------------------------
function assertNoPathLeak(text, where) {
  for (const root of Object.values(ROOTS)) {
    const escaped = root.split("\\").join("\\\\");
    assert(!text.includes(root) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
  assert(!/os error/i.test(text), `a raw OS message leaked into ${where}`);
}
const jargon = ["stable_key", "stableKey", "identity_provenance", "SYS1:", "PFv1:", "fileId", "volumeSerial"];
async function assertConfidential() {
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  for (const word of jargon) assert(!bodyText.includes(word), `jargon « ${word} » leaked into the page`);
  for (const payload of exposedPayloads) assertNoPathLeak(payload, "an invoke payload");
  // What the PRODUCT itself sent to the catalogue: the closed state, no path, no cursor.
  await Promise.all(wireCalls.map((call) => call.bodyReady));
  const writes = wireCalls.filter((c) => c.command === "map_brain_resume_update");
  for (const call of writes) {
    assertNoPathLeak(call.body, "a resume write");
    assert(!/ftf1|cursor/i.test(call.body), "a filter cursor was sent to be stored");
  }
  // The scan above is only worth something if the bodies were really read.
  const readable = writes.filter((call) => call.body.includes("detailsPanelVisible"));
  results.resumeWritesOnTheWire = writes.length;
  results.resumeWriteBodiesInspected = readable.length;
  if (writes.length > 0) assert(readable.length === writes.length, "every resume write body was inspected");
}

// ---- brain-level actions -------------------------------------------------------------
const waitApp = async () => {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
};
const shownAlone = (brainId) => async () => {
  const s = await screenState();
  return s.chips.length === 1 && s.chips[0] === brainId && s.nodeIds.length > 0;
};
/** The way a person switches: bring the other brain in, then let this one go. */
async function switchTo(toKey, fromKey) {
  await click('[data-testid="composition-add-trigger"]');
  await until(`!!document.querySelector('[data-testid="composition-add-item-${IDS[toKey]}"]')`);
  await click(`[data-testid="composition-add-item-${IDS[toKey]}"]`);
  await until(`!!document.querySelector('[data-testid="composition-chip-${IDS[toKey]}"]')`);
  await pause(500);
  await click(`[data-testid="composition-remove-${IDS[fromKey]}"]`);
  await untilTrue(`${toKey} shown alone`, shownAlone(IDS[toKey]), 60000);
  await pause(600);
}
const wireSince = (from, command) => wireCalls.slice(from).filter((call) => call.command === command);

/** One brain's screen, exactly as compared: what a person sees, as values. */
async function brainSnapshot(key) {
  const screen = await screenState();
  const record = await resumeOf(IDS[key]);
  assertRecordShape(record, `${key} record`);
  return { screen, record };
}
function diffSnapshots(key, expected, actual, { exactPage = true } = {}) {
  const problems = [];
  const eq = (label, a, b) => {
    if (JSON.stringify(a) !== JSON.stringify(b)) problems.push(`${key} ${label}: expected ${JSON.stringify(a)}, got ${JSON.stringify(b)}`);
  };
  const e = expected.screen;
  const a = actual.screen;
  eq("chips", [IDS[key]], a.chips);
  eq("selectedId", e.selectedId, a.selectedId);
  eq("selectedName", e.selectedName, a.selectedName);
  eq("panelVisible", e.panelVisible, a.panelVisible);
  eq("filterSentence", e.filterSentence, a.filterSentence);
  eq("filterTotal", e.filterTotal, a.filterTotal);
  if (exactPage) eq("filterPage", e.filterPage, a.filterPage);
  if (!sameView(e.view, a.view)) problems.push(`${key} camera: expected ${JSON.stringify(e.view)}, got ${JSON.stringify(a.view)}`);
  // The record read from the catalogue, value by value (the camera to 1e-6).
  const r = expected.record;
  const s = actual.record;
  eq("record.focusNodeId", r.focusNodeId, s.focusNodeId);
  eq("record.selectedNodeId", r.selectedNodeId, s.selectedNodeId);
  eq("record.filter", r.filter, s.filter);
  eq("record.detailsPanelVisible", r.detailsPanelVisible, s.detailsPanelVisible);
  if (r.view === null || s.view === null ? r.view !== s.view : !sameView(r.view, s.view)) {
    problems.push(`${key} record.view: expected ${JSON.stringify(r.view)}, got ${JSON.stringify(s.view)}`);
  }
  // Everything on the screen is this brain's own: every label begins with its display name.
  const foreign = a.labels.filter((label) => !label.startsWith(`${NAMES[key]} ·`));
  if (foreign.length > 0) problems.push(`${key}: ${foreign.length} node(s) not labelled with its own name`);
  return problems;
}
async function untilBrainIs(key, expected, label, options) {
  let problems = ["never sampled"];
  await untilTrue(
    label,
    async () => {
      const actual = await brainSnapshot(key);
      problems = diffSnapshots(key, expected, actual, options);
      return problems.length === 0;
    },
    60000,
    400,
  ).catch(() => {
    throw new Error(`${label}: ${problems.join("; ")}`);
  });
}

const results = {};
await until(`!!window.__TAURI_INTERNALS__`);
if (phase === 1) await waitApp();

// =====================================================================================
if (phase === 1) {
  // ---- 1 — baseline: one click on Actualiser for X; Y and Z are indexed by the same command
  await click('[data-testid="lifecycle-refresh"]');
  await until(`(document.querySelector('[data-testid="composed-total"]')?.textContent ?? '').length > 0`);
  await untilTrue("X indexed and shown", async () => (await screenState()).nodeIds.length > 3, 120000);
  await invoke("map_refresh", { brainId: IDS.Y });
  await invoke("map_refresh", { brainId: IDS.Z });
  const baselines = {};
  for (const key of ["X", "Y", "Z"]) {
    const opened = await invoke("map_open", { brainId: IDS[key] });
    const journal = await invoke("map_change_journal", { brainId: IDS[key], natures: [], after: null, limit: 5 });
    baselines[key] = { revision: opened.revision, nodeCount: opened.nodeCount, journalTotal: journal.total };
  }
  // root + docs + 200 files + notes + 5 files + x-fin.txt ; Y: 22 ; Z: 190.
  assert.equal(baselines.X.nodeCount, 209, "X node count");
  assert.equal(baselines.Y.nodeCount, 22, "Y node count");
  assert.equal(baselines.Z.nodeCount, 190, "Z node count");
  results.baselines = baselines;

  // The trap: the id of `docs` is the same number in the three brains.
  const rootView = async (key) => invoke("map_view", { brainId: IDS[key] });
  const docsOf = async (key) => (await rootView(key)).nodes.find((n) => n.name === "docs");
  const [dx, dy, dz] = [await docsOf("X"), await docsOf("Y"), await docsOf("Z")];
  assert(dx && dy && dz, "each brain has a docs directory at its root");
  assert.equal(dx.id, dy.id);
  assert.equal(dy.id, dz.id);
  const D = dx.id;
  results.sharedDocsId = D;

  const expected = {};

  // ---- 2 — brain X: branch `docs`, FILE filter, page 3, a match past the first page, panel hidden, zoom
  assert.equal((await screenState()).chips[0], IDS.X);
  await click(`[data-node-id="${D}"]`);
  await untilTrue("docs selected in X", async () => (await screenState()).selectedId === D);
  await clickButtonNamed("Explorer la sélection");
  await untilTrue("X focused on docs", async () => {
    const focused = await invoke("map_view", { brainId: IDS.X, focusId: D });
    const s = await screenState();
    return s.nodeIds.length === focused.nodes.length && s.nodeIds.includes(D) && (await resumeOf(IDS.X)).focusNodeId === D;
  });
  await click('[data-testid="filter-kind-FILE"]');
  await until(`document.querySelector('[data-testid="filter-count"]')?.getAttribute('data-total') === '206'`);
  const firstPageX = (await invoke("map_view", { brainId: IDS.X, filter: { state: "ALL", kinds: ["FILE"], availability: "ALL" } })).filtered
    .filterMatchIds;
  await click('[data-testid="filter-next"]');
  await until(`document.querySelector('[data-testid="filter-page"]')?.textContent.includes('Page 2')`);
  await click('[data-testid="filter-next"]');
  await until(`document.querySelector('[data-testid="filter-page"]')?.textContent.includes('Page 3')`);
  const beforePickX = (await screenState()).selectedId;
  await clickFirstMatch();
  await untilTrue("a match of page 3 is selected in X", async () => {
    const s = await screenState();
    return s.selectedId !== null && s.selectedId !== beforePickX;
  }, 20000);
  const afterPick = await screenState();
  assert(afterPick.selectedId !== null && afterPick.selectedId !== 1 && !firstPageX.includes(afterPick.selectedId), `the selection is a match beyond the first page (${afterPick.selectedId})`);
  results.selectedX = { id: afterPick.selectedId, name: afterPick.selectedName, firstPageHadIt: false };
  await click('[data-testid="details-panel-toggle"]');
  await untilTrue("X panel hidden", async () => (await screenState()).panelVisible === false);
  // A burst of real wheel notches: measured on the wire, it must be a bounded number of writes.
  const burstFrom = wireCalls.length;
  const burstStart = Date.now();
  await wheel(0.3, 0.4, -120, 60, 15);
  const burstMs = Date.now() - burstStart;
  const recordX = await settledRecord(IDS.X, (r) => r.view !== null && r.selectedNodeId === afterPick.selectedId && r.detailsPanelVisible === false, "X state");
  const burstWrites = wireSince(burstFrom, "map_brain_resume_update").length;
  results.wheelBurst = { notches: 60, milliseconds: burstMs, resumeWritesOnTheWire: burstWrites };
  assert(burstWrites <= 4, `a 60-notch wheel burst wrote ${burstWrites} times`);
  assert(burstWrites >= 1, "the burst was persisted");
  expected.X = await brainSnapshot("X");
  assert.equal(recordX.focusNodeId, D, "X's branch is docs");
  assert.deepEqual(recordX.filter, { state: "ALL", kinds: ["FILE"], availability: "ALL" });

  // ---- 3 — brain Y: root branch, `docs` selected (the SAME id as X's branch), panel visible, panned
  await switchTo("Y", "X");
  await click(`[data-node-id="${D}"]`);
  await untilTrue("docs selected in Y", async () => (await screenState()).selectedId === D);
  await drag(0.55, 0.6, -90, -40);
  await wheel(0.7, 0.3, 60, 4, 30);
  await settledRecord(IDS.Y, (r) => r.view !== null && r.selectedNodeId === D, "Y state");
  expected.Y = await brainSnapshot("Y");
  assert.equal(expected.Y.record.detailsPanelVisible, true);
  assert.equal(expected.Y.record.focusNodeId, null);
  assert.deepEqual(expected.Y.record.filter, { state: "ALL", kinds: [], availability: "ALL" });
  assert.notEqual(JSON.stringify(expected.Y.record), JSON.stringify(expected.X.record));

  // ---- 4 — brain Z: branch `salles`, DIRECTORY filter, page 2, a match past the first page, panel hidden
  await switchTo("Z", "Y");
  const salles = (await rootView("Z")).nodes.find((n) => n.name === "salles");
  await click(`[data-node-id="${salles.id}"]`);
  await untilTrue("salles selected in Z", async () => (await screenState()).selectedId === salles.id);
  await clickButtonNamed("Explorer la sélection");
  await untilTrue("Z focused on salles", async () => (await resumeOf(IDS.Z)).focusNodeId === salles.id);
  await click('[data-testid="filter-kind-DIRECTORY"]');
  await until(`(document.querySelector('[data-testid="filter-count"]')?.getAttribute('data-total') ?? '') !== ''`);
  const firstPageZ = (await invoke("map_view", { brainId: IDS.Z, filter: { state: "ALL", kinds: ["DIRECTORY"], availability: "ALL" } })).filtered
    .filterMatchIds;
  await click('[data-testid="filter-next"]');
  await until(`document.querySelector('[data-testid="filter-page"]')?.textContent.includes('Page 2')`);
  const beforePickZ = (await screenState()).selectedId;
  await clickFirstMatch();
  await untilTrue("a match of page 2 is selected in Z", async () => {
    const s = await screenState();
    return s.selectedId !== null && s.selectedId !== beforePickZ;
  }, 20000);
  const pickedZ = await screenState();
  assert(pickedZ.selectedId !== null && pickedZ.selectedId !== 1 && !firstPageZ.includes(pickedZ.selectedId), `Z's selection is a match beyond the first page (${pickedZ.selectedId})`);
  results.selectedZ = { id: pickedZ.selectedId, name: pickedZ.selectedName };
  await click('[data-testid="details-panel-toggle"]');
  await untilTrue("Z panel hidden", async () => (await screenState()).panelVisible === false);
  await wheel(0.6, 0.5, -60, 5, 40);
  await settledRecord(IDS.Z, (r) => r.view !== null && r.selectedNodeId === pickedZ.selectedId && r.detailsPanelVisible === false, "Z state");
  expected.Z = await brainSnapshot("Z");
  assert.equal(expected.Z.record.focusNodeId, salles.id);
  assert.deepEqual(expected.Z.record.filter, { state: "ALL", kinds: ["DIRECTORY"], availability: "ALL" });

  // The three states are pairwise different on every dimension that can differ.
  const states = ["X", "Y", "Z"].map((k) => expected[k].record);
  console.error("phase 1 states", JSON.stringify(states));
  for (const [i, j] of [[0, 1], [0, 2], [1, 2]]) {
    assert.notDeepEqual(states[i].view, states[j].view, "cameras differ");
    assert.notEqual(states[i].selectedNodeId, states[j].selectedNodeId, "selections differ");
    assert.notDeepEqual(states[i].filter, states[j].filter, "filters differ");
  }
  assert.equal(states[0].focusNodeId, D);
  assert.equal(states[1].selectedNodeId, D, "the same numeric id, two different meanings");
  assert.notEqual(states[0].detailsPanelVisible, states[1].detailsPanelVisible, "the panel differs between X and Y");

  // ---- 5 — Z -> X -> Z -> Y in the same session: every return is what was left
  await switchTo("X", "Z");
  await untilBrainIs("X", expected.X, "back on X", { exactPage: false });
  await switchTo("Z", "X");
  await untilBrainIs("Z", expected.Z, "back on Z", { exactPage: false });
  await switchTo("Y", "Z");
  await untilBrainIs("Y", expected.Y, "back on Y");
  results.sessionCycle = ["X", "Y", "Z", "X", "Z", "Y"];

  // Nothing about the source moved: the resume writes are not events of the Index.
  for (const key of ["X", "Y", "Z"]) {
    const opened = await invoke("map_open", { brainId: IDS[key] });
    const journal = await invoke("map_change_journal", { brainId: IDS[key], natures: [], after: null, limit: 5 });
    assert.equal(opened.revision, baselines[key].revision, `${key}: the revision did not move`);
    assert.equal(journal.total, baselines[key].journalTotal, `${key}: the journal did not grow`);
  }
  results.indexAndJournalUntouchedByResumeWrites = true;

  // The last active brain is what the catalogue would reopen.
  const catalogue = await invoke("map_brains");
  assert.equal(catalogue.activeBrainId, IDS.Y);
  results.activeAtClose = "Y";
  results.expected = expected;
  await assertConfidential();
  await writeJson("phase1.json", results);
  await writeJson("phase1-fatal-count.json", fatal.length);
  console.log(JSON.stringify({ ok: true, phase }));
  process.exit(fatal.length === 0 ? 0 : 1);
}

// =====================================================================================
if (phase === 2) {
  const before = await readJson("phase1.json");
  const { expected } = before;
  const D = before.sharedDocsId;
  await waitApp();
  // The last active brain came back ALONE, with its state.
  await untilTrue("Y alone", shownAlone(IDS.Y), 90000);
  results.reopenedAlone = "Y";
  const restoresOnBoot = wireCalls.filter((c) => c.command === "map_brain_resume_restore");
  assert.equal(restoresOnBoot.length, 1, "one restore at boot: only the active brain");
  await untilBrainIs("Y", expected.Y, "Y after the restart");
  const restartRecords = { Y: (await brainSnapshot("Y")).record };

  await switchTo("Z", "Y");
  await untilBrainIs("Z", expected.Z, "Z after the restart", { exactPage: false });
  // « Actualiser » does not erase the state.
  await click('[data-testid="lifecycle-refresh"]');
  await pause(3000);
  await untilBrainIs("Z", expected.Z, "Z after Actualiser", { exactPage: false });
  results.actualiserKeepsTheState = true;
  restartRecords.Z = (await brainSnapshot("Z")).record;

  await switchTo("X", "Z");
  await untilBrainIs("X", expected.X, "X after the restart", { exactPage: false });
  restartRecords.X = (await brainSnapshot("X")).record;
  const shownX = await screenState();
  // The restored page is the one that holds the same node, past the first page.
  assert.equal(shownX.selectedId, expected.X.screen.selectedId);
  assert(shownX.nodeIds.includes(expected.X.screen.selectedId), "the selected match is on the restored page");
  assert(/Page reprise/.test(shownX.filterPage ?? ""), `the restored page says it was resumed (${shownX.filterPage})`);

  // No filter cursor was ever stored, whatever the restart did.
  for (const key of ["X", "Y", "Z"]) {
    assert(!/ftf1/.test(JSON.stringify(restartRecords[key])), `${key}: no cursor in the record`);
  }
  // The node each brain has selected, as a relative path, for the offline phase.
  const selectedPath = {};
  for (const key of ["X", "Y"]) {
    const record = await resumeOf(IDS[key]);
    const detail = await invoke("map_node_detail", { reference: { brainId: IDS[key], nodeId: record.selectedNodeId } });
    selectedPath[key] = detail.node.relativePath;
  }
  assert.equal(selectedPath.Y, "docs", "Y's selection is its docs directory");
  results.selectedPath = selectedPath;
  results.recordsAfterRestart = restartRecords;
  results.sharedDocsId = D;
  results.activeAtClose = "X";
  await assertConfidential();
  await writeJson("phase2.json", results);
  await writeJson("phase2-fatal-count.json", fatal.length);
  console.log(JSON.stringify({ ok: true, phase }));
  process.exit(fatal.length === 0 ? 0 : 1);
}

// =====================================================================================
if (phase === 3) {
  const before = await readJson("phase1.json");
  const middle = await readJson("phase2.json");
  const { expected } = before;
  const D = before.sharedDocsId;
  const removedSelectionX = expected.X.screen.selectedId;
  await waitApp();
  await untilTrue("X alone", shownAlone(IDS.X), 90000);
  const journalX0 = await invoke("map_change_journal", { brainId: IDS.X, natures: ["DELETED"], after: null, limit: 5 });

  // The watcher converges the Index while the application starts: the deleted node leaves it.
  await untilTrue(
    "X's Index no longer has the deleted file",
    async () => {
      const opened = await invoke("map_open", { brainId: IDS.X });
      return opened.nodeCount === before.baselines.X.nodeCount - 1;
    },
    120000,
    300,
  );
  // ... and the interface falls back: the selected node is valid, it is not the deleted one.
  await untilTrue(
    "X's selection is valid again",
    async () => {
      const s = await screenState();
      return s.selectedId !== null && s.selectedId !== removedSelectionX && s.nodeIds.includes(s.selectedId);
    },
    60000,
    300,
  );
  const recordX = await settledRecord(IDS.X, (r) => r.selectedNodeId !== removedSelectionX, "X corrected", 60000);
  const afterX = await screenState();
  const detail = await invoke("map_node_detail", { reference: { brainId: IDS.X, nodeId: afterX.selectedId } });
  assert.equal(detail.node.id, afterX.selectedId, "the fallback selection exists in the current Index");
  await assert.rejects(
    () => invoke("map_node_detail", { reference: { brainId: IDS.X, nodeId: removedSelectionX } }),
    "the deleted node is gone from the Index",
  );
  assert(recordX.selectedNodeId === null || recordX.selectedNodeId === 1, `the record holds no stale id (${recordX.selectedNodeId})`);
  assert.deepEqual(recordX.filter, expected.X.record.filter, "the filter stays authoritative");
  assert.equal(recordX.focusNodeId, D, "X's branch is still docs");
  assert.equal(recordX.detailsPanelVisible, false);
  assert.equal(afterX.filterTotal, 205, "the filter was read again on the new revision");
  assert.equal(afterX.panelVisible, false);
  results.X = { fallbackSelected: afterX.selectedId, recordSelected: recordX.selectedNodeId, filterTotal: afterX.filterTotal };

  // Y: its `docs` directory — the numeric id X uses as its branch — is gone from Y's Index only.
  await switchTo("Y", "X");
  await untilTrue(
    "Y's Index no longer has docs",
    async () => (await invoke("map_open", { brainId: IDS.Y })).nodeCount === before.baselines.Y.nodeCount - 13,
    120000,
    300,
  );
  await untilTrue(
    "Y's selection is valid again",
    async () => {
      const s = await screenState();
      return s.selectedId !== null && s.nodeIds.includes(s.selectedId) && s.selectedName !== "docs";
    },
    60000,
    300,
  );
  const recordY = await settledRecord(IDS.Y, (r) => r.selectedNodeId === null || r.selectedNodeId === 1, "Y corrected", 60000);
  const afterY = await screenState();
  assert.equal(recordY.detailsPanelVisible, true);
  assert.deepEqual(recordY.filter, expected.Y.record.filter);
  assert(sameView(recordY.view, expected.Y.record.view) || recordY.view !== null, "Y's camera is a valid stored camera");
  results.Y = { fallbackSelected: afterY.selectedId, recordSelected: recordY.selectedNodeId };
  // Removing Y's D did not touch X's record: the id is the same number, the brains are two.
  const recordXAfterY = await resumeOf(IDS.X);
  assert.equal(recordXAfterY.focusNodeId, D, "X still keeps its own docs after Y lost its");

  // Z was not touched: exactly what it was.
  await switchTo("Z", "Y");
  await untilBrainIs("Z", expected.Z, "Z after the offline change", { exactPage: false });
  results.ZExactAfterOffline = true;

  await assertConfidential();
  results.noFatal = fatal.length === 0;
  await writeJson("phase3.json", results);
  await writeJson("phase3-fatal-count.json", fatal.length);
  console.log(JSON.stringify({ ok: true, phase }));
  process.exit(fatal.length === 0 ? 0 : 1);
}
